[components-collection-table-index] Table > Usage > Reordering

Table — Display and interact with structured data in rows and columns.

When the order of items matters and users need to manually arrange them, enable drag and drop. This works well for priority lists, custom orderings, or workflows where sequence is important.

> ℹ️ Keyboard support and multiple items: Reordering is fully keyboard accessible. Users can also move multiple items at
> once by selecting them before initiating the drag operation.

```tsx title="table-drag-drop"
import { venues } from '@/lib/data/venues';
import { Table, Text, useDragAndDrop, useListData } from '@marigold/components';

export default () => {
  const list = useListData({
    initialItems: venues.slice(0, 5),
  });

  const { dragAndDropHooks } = useDragAndDrop({
    renderDropIndicator: Table.renderDropIndicator,
    renderDragPreview: Table.renderDragPreview,
    getItems: keys =>
      [...keys].map(key => ({
        'text/plain': list.getItem(key)!.name,
      })),
    onReorder(e) {
      if (e.target.dropPosition === 'before') {
        list.moveBefore(e.target.key, e.keys);
      } else if (e.target.dropPosition === 'after') {
        list.moveAfter(e.target.key, e.keys);
      }
    },
  });

  return (
    <Table
      aria-label="Reorderable venues"
      selectionMode="multiple"
      dragAndDropHooks={dragAndDropHooks}
    >
      <Table.Header>
        <Table.Column rowHeader>Venue</Table.Column>
        <Table.Column>City</Table.Column>
      </Table.Header>
      <Table.Body items={list.items}>
        {item => (
          <Table.Row>
            <Table.Cell>
              <Text weight="medium">{item.name}</Text>
            </Table.Cell>
            <Table.Cell>
              <Text size="sm" color="secondary">
                {item.city}, {item.country}
              </Text>
            </Table.Cell>
          </Table.Row>
        )}
      </Table.Body>
    </Table>
  );
};
```

originalText:
When the order of items matters and users need to manually arrange them, enable drag and drop. This works well for priority lists, custom orderings, or workflows where sequence is important.

> ℹ️ Keyboard support and multiple items: Reordering is fully keyboard accessible. Users can also move multiple items at
> once by selecting them before initiating the drag operation.

```tsx title="table-drag-drop"
import { venues } from '@/lib/data/venues';
import { Table, Text, useDragAndDrop, useListData } from '@marigold/components';

export default () => {
  const list = useListData({
    initialItems: venues.slice(0, 5),
  });

  const { dragAndDropHooks } = useDragAndDrop({
    renderDropIndicator: Table.renderDropIndicator,
    renderDragPreview: Table.renderDragPreview,
    getItems: keys =>
      [...keys].map(key => ({
        'text/plain': list.getItem(key)!.name,
      })),
    onReorder(e) {
      if (e.target.dropPosition === 'before') {
        list.moveBefore(e.target.key, e.keys);
      } else if (e.target.dropPosition === 'after') {
        list.moveAfter(e.target.key, e.keys);
      }
    },
  });

  return (
    <Table
      aria-label="Reorderable venues"
      selectionMode="multiple"
      dragAndDropHooks={dragAndDropHooks}
