                {item.city}, {item.country}
              </Text>
            </Table.Cell>
          </Table.Row>
        )}
      </Table.Body>
    </Table>
  );
};
```

When a table has no data to display, whether from empty search results, filters with no matches, or newly created lists, show a helpful empty state instead of a blank table body.

```tsx title="table-empty"
import { Button, EmptyState, Table } from '@marigold/components';

export default () => (
  <Table aria-label="Empty table">
    <Table.Header>
      <Table.Column rowHeader>Name</Table.Column>
      <Table.Column>Email</Table.Column>
      <Table.Column>Status</Table.Column>
    </Table.Header>
    <Table.Body
      emptyState={() => (
        <EmptyState
          title="No results found"
          description="Try adjusting your search or filters to find what you're looking for."
          action={
            <Button size="small" variant="primary">
              Reset search and filter
            </Button>
          }
        />
      )}
    >
      {[]}
    </Table.Body>
  </Table>
);
```

✓ Include action buttons in empty states when appropriate, like "Add first item" or "Clear filters".

✗ Don't show a generic "No data" message without context or next steps.

For tables with many rows that require scrolling, sticky headers keep column labels visible as users scroll through data. This helps users maintain context about what each column represents.

```tsx title="table-sticky"
import { venues } from '@/lib/data/venues';
import { NumericFormat, Scrollable, Table, Text } from '@marigold/components';

export default () => {
  return (
    <Scrollable height="300px">
      <Table aria-label="Long scrollable table">
        <Table.Header sticky>
          <Table.Column rowHeader>Venue</Table.Column>
          <Table.Column>City</Table.Column>
          <Table.Column alignX="right">Capacity</Table.Column>
        </Table.Header>
        <Table.Body>
          {venues.map(venue => (
            <Table.Row key={venue.id}>
              <Table.Cell>
                <Text weight="medium">{venue.name}</Text>
              </Table.Cell>
              <Table.Cell>
                {venue.city}, {venue.country}
              </Table.Cell>
              <Table.Cell>
                <NumericFormat value={venue.capacity} />
              </Table.Cell>
            </Table.Row>
          ))}
        </Table.Body>
      </Table>
    </Scrollable>
  );
};
```

✓ Use sticky headers for tables with more than 10-15 rows where scrolling is necessary.

✗ Don't make headers sticky for short tables where all rows fit on screen without scrolling.

Table footers can be sticky too, keeping the summary row visible while users scroll through long tables.

```tsx title="table-footer-sticky"
import { venues } from '@/lib/data/venues';
import { NumericFormat, Scrollable, Table } from '@marigold/components';

export default () => {
  const totalCapacity = venues.reduce((sum, venue) => sum + venue.capacity, 0);

  return (
    <Scrollable height="300px">
      <Table aria-label="Long scrollable table with sticky totals">
        <Table.Header sticky>
          <Table.Column rowHeader>Venue</Table.Column>
          <Table.Column>City</Table.Column>
          <Table.Column alignX="right">Capacity</Table.Column>
        </Table.Header>
        <Table.Body>
          {venues.map(venue => (
            <Table.Row key={venue.id}>
              <Table.Cell>{venue.name}</Table.Cell>
              <Table.Cell>
                {venue.city}, {venue.country}
              </Table.Cell>
              <Table.Cell>
                <NumericFormat value={venue.capacity} />
              </Table.Cell>
            </Table.Row>
          ))}
        </Table.Body>
        <Table.Footer sticky>
          <Table.Row>
            <Table.Cell colSpan={2}>Total</Table.Cell>
            <Table.Cell>
              <NumericFormat value={totalCapacity} />
            </Table.Cell>
          </Table.Row>
        </Table.Footer>
      </Table>
    </Scrollable>
  );
};
```

Use `<Table.Footer>` to display a summary row after the table body, such as totals, counts, or averages. Unlike faking a totals row with an extra `<Table.Row>` inside the body, the footer renders as a semantic `<tfoot>`, which keeps it out of the body's scroll and sticky-header semantics and is announced correctly by assistive technology.

Compose the summary row from `<Table.Row>` and `<Table.Cell>` just like the body, using `colSpan` to span a label across multiple columns.

```tsx title="table-footer"
import { venues } from '@/lib/data/venues';
import { NumericFormat, Table } from '@marigold/components';

const data = venues.slice(0, 5);

export default () => {
  const totalCapacity = data.reduce((sum, venue) => sum + venue.capacity, 0);

  return (
    <Table aria-label="Venues with total capacity">
      <Table.Header>
        <Table.Column rowHeader>Venue</Table.Column>
        <Table.Column>City</Table.Column>
        <Table.Column alignX="right">Capacity</Table.Column>
      </Table.Header>
      <Table.Body>
        {data.map(venue => (
          <Table.Row key={venue.id}>
            <Table.Cell>{venue.name}</Table.Cell>
            <Table.Cell>
              {venue.city}, {venue.country}
            </Table.Cell>
            <Table.Cell>
              <NumericFormat value={venue.capacity} />
            </Table.Cell>
          </Table.Row>
        ))}
      </Table.Body>
      <Table.Footer>
        <Table.Row>
          <Table.Cell colSpan={2}>Total</Table.Cell>
          <Table.Cell>
            <NumericFormat value={totalCapacity} />
          </Table.Cell>
        </Table.Row>
      </Table.Footer>
    </Table>
  );
};
```

✓ Use a footer for a single, table-wide summary row like totals or counts.

✗ Don't use a footer to add another data row, use \<Table.Body> for records.

