[components-form-combobox-index] ComboBox > Usage > Working with asynchronous Data

ComboBox — A text-field that allows the user to select values from a provided items array.

The ComboBox component supports working with asynchronous data. In the example below, the [`useAsyncList`](/components/hooks-and-utils/useAsyncList) hook is used to handle the loading and filtering of data from the server.

```tsx title="combobox-async"
import { ComboBox, useAsyncList } from '@marigold/components';

export default () => {
  const list = useAsyncList<{ name: string }>({
    async load({ signal, filterText }) {
      const res = await fetch(
        `https://swapi.py4e.com/api/people/?search=${filterText}`,
        {
          signal,
        }
      );
      const json = await res.json();

      return {
        items: json.results,
      };
    },
  });
  return (
    <ComboBox
      label="Star Wars Character Lookup"
      value={list.filterText}
      onChange={list.setFilterText}
      items={list.items}
    >
      {(item: { name: string }) => (
        <ComboBox.Option id={item.name}>{item.name}</ComboBox.Option>
      )}
    </ComboBox>
  );
};
```

