import { DatePicker } from '@marigold/components';

export default () => {
  const date = new Date().toISOString();
  const [value, setValue] = useState<DateValue>(parseAbsoluteToLocal(date)!);

  return (
    <DatePicker
      label="Date"
      value={value}
      onChange={newValue => setValue(newValue!)}
    />
  );
};
```

### Paste Support

The `<DatePicker>` supports pasting date values from the clipboard. Users can copy dates in common formats and paste them directly into the date picker field. The component automatically parses and validates the pasted content.

**Supported date formats:**

- ISO format: `2023-12-25`
- European format: `25.12.2023` or `25/12/2023`
- US format: `12/25/2023` or `12-25-2023`

Invalid dates or unrecognized formats are ignored, ensuring data integrity.

```tsx title="datepicker-paste"
import { DatePicker, Stack, Text } from '@marigold/components';

export default function () {
  return (
    <Stack space={4}>
      <Text size="small" variant="info">
        Try pasting a date in yyyy-mm-dd format (e.g., &quot;2025-09-24&quot;)
      </Text>
      <DatePicker
        label="Scheduled Date"
        description="You can paste dates directly into this field"
      />
    </Stack>
  );
}
```

### Quick select presets

Use the `presets` prop to offer common dates as a one-click list beside the calendar in the popover, such as "Today" or "Tomorrow" for a due date. Built-in keys ship with localized labels and correct date math, and custom presets take a `label` plus a date value or a resolver function. Presets that fall outside `minValue`/`maxValue` or land on an unavailable date are disabled.

`DatePicker` accepts the single-date built-ins: `today`, `yesterday` and `tomorrow`. Range keys such as `this-week` or `last-30-days` are only available on [DateRangePicker](/components/form/daterangepicker) and [RangeCalendar](/components/form/rangecalendar), where a preset selects a range instead of a single day.

For custom presets, pass `value` as a function when the date is relative to now (for example "In two weeks"), so it resolves at selection time instead of when the view first rendered. A plain value is right for fixed dates. If you provide several custom presets, give each a unique `id`: it defaults to the `label`, so two presets sharing a label would collide.

```tsx title="date-picker-presets"
import { DatePicker } from '@marigold/components';

export default () => (
  <DatePicker
    label="Event date"
    presets={['today', 'tomorrow']} // [!code highlight]
  />
);
```

> ⚠️ Quick select on narrow screens: The picker's overlay is already a bottom sheet on small screens, so a "Quick
> selection" row above the grid switches the sheet to the preset list in place,
> with a Back row to return to the calendar. Picking a preset applies the date
> and returns to the calendar, and the overlay stays open.

#### Combine with a second field

A "From" and "To" pair of `<DatePicker>`s can each carry their own `presets`. Feed the other field's value into `minValue`/`maxValue` so the range stays valid, and pick presets independently for each end.

```tsx title="date-picker-from-to-presets"
import type { DateValue } from '@internationalized/date';
import { useState } from 'react';
import { DatePicker, Stack } from '@marigold/components';

export default () => {
  const [from, setFrom] = useState<DateValue | null>(null);
  const [to, setTo] = useState<DateValue | null>(null);

  return (
    <Stack space={4}>
      <DatePicker
        label="From"
        value={from}
        onChange={setFrom}
        maxValue={to ?? undefined} // [!code highlight]
        presets={['today', 'tomorrow']}
      />
      <DatePicker
        label="To"
        value={to}
        onChange={setTo}
        minValue={from ?? undefined} // [!code highlight]
        presets={['today', 'tomorrow']}
      />
    </Stack>
  );
};
```

