[components-hooks-and-utils-useAsyncList-index] useAsyncList > Examples

useAsyncList — Hook that returns async data

### Async Table

This is an example from the [`<Table>`](/components/collection/table) component. The data will be loaded asynchronously.

```tsx title="async"
import { Table, useAsyncList } from '@marigold/components';

export interface asyncData {
  name: string;
  height: string;
  mass: string;
  birth_year: string;
}

export default () => {
  let list = useAsyncList<asyncData>({
    async load({ signal }) {
      let res = await fetch(`https://swapi.py4e.com/api/people/?search`, {
        signal,
      });
      let json = await res.json();
      return {
        items: json.results,
      };
    },
    async sort({ items, sortDescriptor }) {
      return {
        items: items.sort((a, b) => {
          let first = a[sortDescriptor.column as keyof asyncData];
          let second = b[sortDescriptor.column as keyof asyncData];
          let cmp =
            (parseInt(first) || first) < (parseInt(second) || second) ? -1 : 1;
          if (sortDescriptor.direction === 'descending') {
            cmp *= -1;
          }
          return cmp;
        }),
      };
    },
  });

  return (
    <Table
      aria-label="Example table with client side sorting"
      sortDescriptor={list.sortDescriptor}
      onSortChange={list.sort}
    >
      <Table.Header>
        <Table.Column id="name" allowsSorting rowHeader>
          Name
        </Table.Column>
        <Table.Column id="height" allowsSorting>
          Height
        </Table.Column>
        <Table.Column id="mass" allowsSorting>
          Mass
        </Table.Column>
        <Table.Column id="birth_year" allowsSorting>
          Birth Year
        </Table.Column>
      </Table.Header>
