        </Inline>
      ),
      children: (
        <Stack space={2}>
          <TextField
            label="Parking Slots"
            description="Available parking passes"
          />
          <NumberField
            label="Costs"
            description="Amount in euros"
            defaultValue={5}
            formatOptions={{
              style: 'currency',
              currency: 'EUR',
            }}
          />
        </Stack>
      ),
    },
    {
      id: 'two',
      key: 'two',
      textValue: 'Handicapped parking spaces',
      title: (
        <Inline space={2} alignY="center">
          <Accessibility />
          <Text fontStyle="normal">Handicapped parking spaces</Text>
        </Inline>
      ),
      children: (
