                  size="small"
                  aria-label={`Delete ${product.name}`}
                  onPress={() => deleteProduct(product)}
                >
                  <Trash2 size={16} />
                </Button>
              </Table.Cell>
            </Table.Row>
          ))}
        </Table.Body>
      </Table>
      <Button variant="secondary" size="small" onPress={resetDemo}>
        Reset demo
      </Button>
    </Stack>
  );
};

