[patterns-feedback-error-boundaries-index] Error Boundaries > Page tier with react-error-boundary

Error Boundaries — How a failed page or region presents itself, recovers, and stays accessible.

In plain React or React Router, you place the boundary yourself. Put it inside the `Page`, below the `Page.Header`: the header and route title stay mounted, and the fallback is only the `ErrorState`, no duplicated header.

The `resetKeys` line is not optional: a boundary that stays mounted across client-side navigation keeps showing a stale error after the user navigates away and back. Reset on navigation:

```tsx
import { ErrorBoundary } from 'react-error-boundary';
import { useLocation } from 'react-router';

const { pathname } = useLocation();

<Page>
  <Page.Header>
    <Title>Billing</Title>
  </Page.Header>
  <ErrorBoundary
    FallbackComponent={BillingErrorFallback}
    resetKeys={[pathname]}
  >
    <BillingContent />
  </ErrorBoundary>
</Page>;
```

Try it out: breaking the page swaps the content for the fallback while the header keeps the route title as the h1, and focus moves to the error state.

```tsx title="error-page-tier"
import { useEffect, useRef, useState } from 'react';
import { ErrorBoundary, type FallbackProps } from 'react-error-boundary';
import {
  Button,
  Description,
  ErrorState,
  Page,
  Panel,
  Text,
  Title,
} from '@marigold/components';

const BillingErrorFallback = ({ resetErrorBoundary }: FallbackProps) => {
  // Page tier: the task the user was on is gone, so the fallback takes focus.
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => ref.current?.focus(), []);

  return (
    <ErrorState
      ref={ref}
      tabIndex={-1}
      headingLevel={2}
      title="We can't load your billing data"
      description="Something went wrong on our side. Your data is safe."
      action={
        <Button variant="primary" onPress={resetErrorBoundary}>
          Try again
        </Button>
      }
    />
  );
};

const BillingContent = ({ broken }: { broken: boolean }) => {
  if (broken) {
    throw new Error('Failed to fetch billing data');
  }
  return (
    <Panel>
      <Panel.Header>
        <Title>Current plan</Title>
      </Panel.Header>
      <Panel.Content>
        <Text>You are on the Team plan.</Text>
      </Panel.Content>
    </Panel>
  );
};

export default () => {
  const [broken, setBroken] = useState(false);

  return (
    <div>
      <Button size="small" onPress={() => setBroken(true)}>
        Break this page
      </Button>
      <Page>
        <Page.Header>
          {/* The route title stays mounted, keeps the h1, and names the <main> landmark. */}
          <Title>Billing</Title>
          <Description>Manage your plan and invoices.</Description>
        </Page.Header>
        <ErrorBoundary
          FallbackComponent={BillingErrorFallback}
          onReset={() => setBroken(false)}
        >
          <BillingContent broken={broken} />
        </ErrorBoundary>
      </Page>
    </div>
  );
};
```

