[patterns-feedback-error-boundaries-index] Error Boundaries > Region tier inside a Panel

Error Boundaries — How a failed page or region presents itself, recovers, and stays accessible.

The boundary wraps only the panel's content. The fallback is an `ErrorState` with `role="alert"`, so the failure is announced without pulling the user out of a page that still works:

```tsx title="error-region-tier"
import { useState } from 'react';
import { ErrorBoundary, type FallbackProps } from 'react-error-boundary';
import { Button, ErrorState, Panel, Text, Title } from '@marigold/components';

const InvoicesFallback = ({ resetErrorBoundary }: FallbackProps) => (
  <ErrorState
    // Region tier: announce the failure, don't steal focus.
    role="alert"
    // Under the panel's h2.
    headingLevel={3}
    title="Invoices didn't load"
    description="You can retry. The rest of the page is unaffected."
    action={
      <Button variant="primary" size="small" onPress={resetErrorBoundary}>
        Try again
      </Button>
    }
  />
);

const InvoiceList = ({ broken }: { broken: boolean }) => {
  if (broken) {
    throw new Error('Failed to fetch invoices');
  }
  return <Text>3 invoices, all paid.</Text>;
};

export default () => {
  const [broken, setBroken] = useState(false);

  return (
    <Panel>
      <Panel.Header>
        <Title>Recent invoices</Title>
        <Button size="small" onPress={() => setBroken(true)}>
          Break this panel
        </Button>
      </Panel.Header>
      <Panel.Content>
        <ErrorBoundary
          FallbackComponent={InvoicesFallback}
          onReset={() => setBroken(false)}
        >
          <InvoiceList broken={broken} />
        </ErrorBoundary>
      </Panel.Content>
    </Panel>
  );
};
```

