[patterns-user-input-bulk-actions-index] Bulk Actions > Direct actions

Bulk Actions — Let users select many records and act on all of them at once.

Most bulk actions are a single verb that needs no further input: publish, pause, assign, export. Run them straight from the bar the moment they are pressed. Making users confirm a routine, recoverable operation adds friction without safety, and trains them to click through the dialogs that guard the operations that do matter.

After the operation succeeds, confirm the outcome with a [`<Toast>`](/components/overlay/toast) that names the count, and clear the selection. The cleared selection signals that the job is done and prevents the previous scope from silently applying to the next action.

```tsx title="bulk-actions-single-verb"
import { useState } from 'react';
import type { Selection } from '@marigold/components';
import {
  ActionBar,
  Badge,
  Button,
  Table,
  ToastProvider,
  useToast,
} from '@marigold/components';
import { CircleCheck, CirclePause } from '@marigold/icons';

interface Event {
  id: string;
  name: string;
  date: string;
  status: 'On sale' | 'Paused' | 'Draft';
}

const initialEvents: Event[] = [
  { id: '1', name: 'Jazz Night', date: 'Aug 12, 2026', status: 'Draft' },
  { id: '2', name: 'Open Air Kino', date: 'Aug 15, 2026', status: 'Draft' },
  { id: '3', name: 'Poetry Slam', date: 'Aug 21, 2026', status: 'On sale' },
  { id: '4', name: 'Herbstmarkt', date: 'Sep 5, 2026', status: 'Draft' },
  { id: '5', name: 'Wine Tasting', date: 'Sep 12, 2026', status: 'On sale' },
];

const statusVariants = {
  'On sale': 'success',
  Paused: 'warning',
  Draft: 'info',
} as const;

export default () => {
  const [events, setEvents] = useState(initialEvents);
  const [selected, setSelected] = useState<Selection>(new Set());
  const { addToast } = useToast();

  const applyStatus = (status: Event['status']) => {
    // Resolve the selection to a concrete list once, so the count in the
    // toast and the records we change can never disagree.
    // [!code highlight:2]
    const keys =
      selected === 'all' ? events.map(event => event.id) : [...selected];

    setEvents(current =>
      current.map(event =>
        keys.includes(event.id) ? { ...event, status } : event
      )
    );

    const scope = keys.length === 1 ? '1 event' : `${keys.length} events`;
    addToast({
      title: `${scope} ${status === 'On sale' ? 'put on sale' : 'paused'}`,
      variant: 'success',
    });
    setSelected(new Set()); // [!code highlight]
  };

  return (
    <>
      {/* The one toast region for this page: the other bulk-actions demos
          enqueue into the same global queue and render through it. */}
      <ToastProvider position="bottom-right" />
      <Table
        aria-label="Events"
        selectionMode="multiple"
        selectedKeys={selected}
        onSelectionChange={setSelected}
        actionBar={() => (
          <ActionBar>
            <Button onPress={() => applyStatus('On sale')}>
              <CircleCheck />
              Put on sale
            </Button>
            <Button onPress={() => applyStatus('Paused')}>
              <CirclePause />
              Pause sale
            </Button>
          </ActionBar>
        )}
      >
        <Table.Header>
          <Table.Column rowHeader>Event</Table.Column>
          <Table.Column>Date</Table.Column>
          <Table.Column>Status</Table.Column>
        </Table.Header>
        <Table.Body>
          {events.map(event => (
            <Table.Row key={event.id} id={event.id}>
              <Table.Cell>{event.name}</Table.Cell>
              <Table.Cell>{event.date}</Table.Cell>
              <Table.Cell>
                <Badge variant={statusVariants[event.status]}>
                  {event.status}
                </Badge>
              </Table.Cell>
            </Table.Row>
          ))}
        </Table.Body>
      </Table>
    </>
  );
};
```

