[patterns-user-input-bulk-actions-index] Bulk Actions > Confirming destructive actions

Bulk Actions — Let users select many records and act on all of them at once.

Destructive bulk actions multiply the cost of a mistake by the size of the selection, and without an undo system a confirmation dialog is the only safety net. Every destructive bulk action goes through one, using the `useConfirmation` hook from [`<Dialog>`](/components/overlay/dialog).

A bare "Are you sure?" protects nobody. The dialog must restate what is about to happen with the exact count and a summary of the impact, so the user can catch a wrong selection at the last moment:

> Delete 12 events? This will cancel 47 ticket reservations and notify 138 customers.

Repeat the action verb and the count in the confirm button, "Delete 12 events" rather than "OK", so the button reads as the decision it is. Focus the cancel button when the dialog opens, so pressing  out of habit chooses the safe path.

```tsx title="bulk-actions-confirm"
import { useState } from 'react';
import type { Selection } from '@marigold/components';
import {
  ActionBar,
  Button,
  Inline,
  Stack,
  Table,
  useConfirmation,
  useToast,
} from '@marigold/components';
import { RotateCcw, Trash2 } from '@marigold/icons';

interface Event {
  id: string;
  name: string;
  date: string;
  reservations: number;
}

const initialEvents: Event[] = [
  { id: '1', name: 'Jazz Night', date: 'Aug 12, 2026', reservations: 47 },
  { id: '2', name: 'Open Air Kino', date: 'Aug 15, 2026', reservations: 112 },
  { id: '3', name: 'Poetry Slam', date: 'Aug 21, 2026', reservations: 0 },
  { id: '4', name: 'Herbstmarkt', date: 'Sep 5, 2026', reservations: 23 },
  { id: '5', name: 'Wine Tasting', date: 'Sep 12, 2026', reservations: 65 },
];

export default () => {
  const [events, setEvents] = useState(initialEvents);
  const [selected, setSelected] = useState<Selection>(new Set());
  const confirm = useConfirmation();
  const { addToast } = useToast();

  const deleteSelected = async () => {
    const keys =
      selected === 'all' ? events.map(event => event.id) : [...selected];
    const affected = events.filter(event => keys.includes(event.id));
    const reservations = affected.reduce(
      (sum, event) => sum + event.reservations,
      0
    );
    const scope =
      affected.length === 1 ? '1 event' : `${affected.length} events`;

    // Name the exact count and the impact, repeat the verb in the confirm
    // button, and focus Cancel so a reflexive Enter takes the safe path.
    // [!code highlight:8]
    const result = await confirm({
      variant: 'destructive',
      title: `Delete ${scope}?`,
      content: `This will cancel ${reservations} ticket reservations and notify the ticket buyers. This action cannot be undone.`,
      confirmationLabel: `Delete ${scope}`,
      cancelLabel: 'Cancel',
      autoFocusButton: 'cancel',
    });

    if (result === 'confirmed') {
      setEvents(current => current.filter(event => !keys.includes(event.id)));
      setSelected(new Set());
      addToast({
        title: `${scope} deleted`,
        variant: 'success',
      });
    }
  };

  return (
    <Stack space={2}>
      <Table
        aria-label="Events"
        selectionMode="multiple"
        selectedKeys={selected}
        onSelectionChange={setSelected}
        actionBar={() => (
          <ActionBar>
            <Button onPress={deleteSelected}>
              <Trash2 />
              Delete
            </Button>
          </ActionBar>
        )}
      >
        <Table.Header>
          <Table.Column rowHeader>Event</Table.Column>
          <Table.Column>Date</Table.Column>
          <Table.Column>Reservations</Table.Column>
        </Table.Header>
        <Table.Body>
          {events.map(event => (
            <Table.Row key={event.id} id={event.id}>
              <Table.Cell>{event.name}</Table.Cell>
              <Table.Cell>{event.date}</Table.Cell>
              <Table.Cell>{event.reservations}</Table.Cell>
            </Table.Row>
          ))}
        </Table.Body>
      </Table>
      {events.length < initialEvents.length && (
        <Inline alignX="right">
          <Button
            variant="ghost"
            size="small"
            onPress={() => setEvents(initialEvents)}
          >
            <RotateCcw />
            Reset demo
          </Button>
        </Inline>
      )}
    </Stack>
  );
};
```

✓ Confirm destructive bulk actions with the exact count and impact, and repeat the verb in the confirm button.

✗ Don't confirm routine, recoverable actions. Overused dialogs train users to click through the one that matters.

