[patterns-user-input-bulk-actions-index] Bulk Actions > Showing progress

Bulk Actions — Let users select many records and act on all of them at once.

Bulk operations in Reservix products run synchronously: the user starts the operation, watches it complete, and sees the result in the same session. There is no background-job or notification pattern to design for, which keeps the feedback model simple and tied to how long the operation takes:

- **Under about two seconds**, feedback on the pressed control is enough: set the [`<Button>`](/components/actions/button) `loading` prop.
- **Between two and ten seconds**, show progress with a running count where the actions were, "Sending 4 of 12", so the user sees the operation moving through the selection. Keep the bar visible and the selection intact while it runs.
- **Beyond ten seconds**, users lose attention and need a way to interrupt. No current Reservix bulk operation crosses this line. If yours does, the operation needs product-level rework rather than a bigger spinner.

Disable the other actions in the bar while an operation runs, so two bulk operations cannot race on the same selection. For the general feedback vocabulary of spinners and skeletons, see the [Loading States](/patterns/feedback/loading-states) pattern.

```tsx title="bulk-actions-progress"
import { useState } from 'react';
import type { Selection } from '@marigold/components';
import {
  ActionBar,
  Button,
  Inline,
  ProgressCircle,
  Table,
  Text,
  useToast,
} from '@marigold/components';
import { Download, Send } from '@marigold/icons';

const events = [
  { id: '1', name: 'Jazz Night', tickets: 214 },
  { id: '2', name: 'Open Air Kino', tickets: 460 },
  { id: '3', name: 'Poetry Slam', tickets: 95 },
  { id: '4', name: 'Herbstmarkt', tickets: 310 },
  { id: '5', name: 'Wine Tasting', tickets: 58 },
  { id: '6', name: 'Klassik im Park', tickets: 127 },
];

const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export default () => {
  const [selected, setSelected] = useState<Selection>(
    new Set(events.map(event => event.id))
  );
  const [exporting, setExporting] = useState(false);
  const [sending, setSending] = useState<{ done: number; total: number }>();
  const { addToast } = useToast();

  const count = selected === 'all' ? events.length : selected.size;

  // A quick operation: the pressed button carries the feedback.
  const exportSelected = async () => {
    setExporting(true);
    await wait(1500);
    setExporting(false);
    addToast({
      title: count === 1 ? '1 event exported' : `${count} events exported`,
      variant: 'success',
    });
    setSelected(new Set());
  };

  // A longer, per-record operation: the bar reports the running count.
  const sendReminders = async () => {
    for (let done = 0; done < count; done++) {
      setSending({ done, total: count });
      await wait(600);
    }
    setSending(undefined);
    addToast({
      title: count === 1 ? '1 reminder sent' : `${count} reminders sent`,
      variant: 'success',
    });
    setSelected(new Set());
  };

  return (
    <>
      <Table
        aria-label="Events"
        selectionMode="multiple"
        selectedKeys={selected}
        onSelectionChange={setSelected}
        actionBar={() => (
          <ActionBar>
            {sending ? (
              // Longer op: the running count replaces the actions in place,
              // announced politely so it is not just a visual change.
              // [!code highlight:6]
              <Inline space={2} alignY="center">
                <ProgressCircle />
                <Text aria-live="polite">
                  Sending {sending.done + 1} of {sending.total}…
                </Text>
              </Inline>
            ) : (
              <>
                {/* Quick op: feedback rides on the pressed button. */}
                {/* [!code highlight:4] */}
                <Button loading={exporting} onPress={exportSelected}>
                  <Download />
                  Export
                </Button>
                {/* Disable siblings so two operations can't race. */}
                <Button disabled={exporting} onPress={sendReminders}>
                  <Send />
                  Send reminder
                </Button>
              </>
            )}
          </ActionBar>
        )}
      >
        <Table.Header>
          <Table.Column rowHeader>Event</Table.Column>
          <Table.Column>Tickets sold</Table.Column>
        </Table.Header>
        <Table.Body>
          {events.map(event => (
            <Table.Row key={event.id} id={event.id}>
              <Table.Cell>{event.name}</Table.Cell>
              <Table.Cell>{event.tickets}</Table.Cell>
            </Table.Row>
          ))}
        </Table.Body>
      </Table>
    </>
  );
};
```

