textForEmbedding:
[patterns-user-input-pick-index] Pick > The pick dialog

Pick — Find and collect records from a collection, then commit them as a set.

The dialog is the pattern's default surface and the most composed, so it is worth walking through part by part. It gathers a pick into one focused place that floats over the page rather than navigating away, its parts stacked in a predictable order from the trigger that opens it down to the footer that ends it.

A trigger in the host task opens the dialog, such as an "Add venues" button, and nothing is staged until the user opens it and commits. Inside, a title names what is being picked, such as "Select venues". Below the title, a [`<SearchField>`](/components/form/search-field) finds records by name as the user types and narrows the visible rows without touching what is already staged. Optional filter controls sit beside it, criteria such as status or type that slice a large pool further.

The matching records form the results collection, shown as a [`<Table>`](/components/collection/table) when they carry detail worth scanning, such as a city and a capacity, or a plain list when the label is all there is. Checking a row stages it. A commit footer ends the task, where a cancel action discards the staged set and a primary action commits it, carrying the staged count in its label, "Add 3 venues".

The example below adds venues from a searchable, filterable, multi-select table.

```tsx title="pick-dialog"
import { useMemo, useState } from 'react';
import type { Key } from '@react-types/shared';
import type { Selection } from '@marigold/components';
import {
  Button,
  Dialog,
  EmptyState,
  Inline,
  Panel,
  SearchField,
  SectionMessage,
  Select,
  Stack,
  Table,
  Tag,
  Text,
} from '@marigold/components';

const venues = [
  {
    id: 'astra',
    name: 'Astra Kulturhaus',
    city: 'Berlin',
    capacity: '1,500',
    type: 'Club',
  },
  {
    id: 'gruenspan',
    name: 'Grünspan',
    city: 'Hamburg',
    capacity: '1,200',
    type: 'Club',
  },
  {
    id: 'backstage',
    name: 'Backstage',
    city: 'Munich',
    capacity: '900',
    type: 'Club',
  },
  {
    id: 'palladium',
    name: 'Palladium',
    city: 'Cologne',
    capacity: '4,000',
    type: 'Concert Hall',
  },
  {
    id: 'capitol',
    name: 'Capitol',
    city: 'Hanover',
    capacity: '1,350',
    type: 'Concert Hall',
  },
  {
    id: 'zakk',
    name: 'zakk',
    city: 'Dusseldorf',
    capacity: '1,000',
    type: 'Club',
  },
  {
    id: 'batschkapp',
    name: 'Batschkapp',
    city: 'Frankfurt',
    capacity: '1,500',
    type: 'Club',
  },
  {
    id: 'longhorn',
    name: 'LKA Longhorn',
    city: 'Stuttgart',
    capacity: '1,100',
    type: 'Concert Hall',
  },
  {
    id: 'waldbuehne',
    name: 'Waldbühne',
    city: 'Berlin',
    capacity: '22,000',
    type: 'Open Air',
  },
  {
    id: 'loreley',
    name: 'Loreley',
    city: 'St. Goarshausen',
    capacity: '15,000',
    type: 'Open Air',
  },
];

const types = ['Club', 'Concert Hall', 'Open Air'];

interface PickBodyProps {
  initial: Set<Key>;
  onConfirm: (keys: Set<Key>) => void;
}

const PickVenuesBody = ({ initial, onConfirm }: PickBodyProps) => {
  const [search, setSearch] = useState('');
  const [type, setType] = useState<Key | null>('all');
  const [selected, setSelected] = useState<Set<Key>>(() => new Set(initial));
  // Keep the commit active. Counts refused empty presses, which keys the error
  // so each press re-announces, and resets on any selection change.
  const [emptyAttempts, setEmptyAttempts] = useState(0);

  const results = useMemo(() => {
    const query = search.trim().toLowerCase();
    return venues.filter(venue => {
      const matchesSearch =
        !query || `${venue.name} ${venue.city}`.toLowerCase().includes(query);
      const matchesType = type == null || type === 'all' || venue.type === type;
      return matchesSearch && matchesType;
    });
  }, [search, type]);

  // Normalize react-aria's "select all" (which means the visible rows) to a
  // concrete set at the boundary, keeping venues staged under other filters, so
  // narrowing the list never changes what is committed.
  const onSelectionChange = (keys: Selection) => {
    // Any selection change clears a pending empty-press error.
    setEmptyAttempts(0);
    const visibleIds = new Set<Key>(results.map(venue => venue.id));
    setSelected(prev => {
      const offView = [...prev].filter(key => !visibleIds.has(key));
      const visibleSelection = keys === 'all' ? [...visibleIds] : [...keys];
      return new Set<Key>([...offView, ...visibleSelection]);
    });
  };

  const unstage = (keys: Set<Key>) => {
    setSelected(prev => {
      const next = new Set<Key>(prev);
      keys.forEach(key => next.delete(key));
      return next;
    });
  };

  // The staged set is derived from `selected` alone, so it is independent of
  // the search and filter above and survives the list narrowing to nothing.
  const staged = venues.filter(venue => selected.has(venue.id));

  return (
    <>
      {/* State the one-venue minimum up front as the dialog's accessible
          description, so it is announced to a screen reader on the table or
          footer instead of only being read in visual order. */}
      <Dialog.Header>
        <Dialog.Title>Select venues</Dialog.Title>
        <Dialog.Description>
          Pick at least one venue to add it.
        </Dialog.Description>
      </Dialog.Header>
      <Dialog.Content>
        <Stack space={4}>
          {/* An empty press reveals this instead of committing, and the key
              remounts it so each refused press re-announces. Any selection
              change resets the counter and hides it. */}
          <SectionMessage
            key={emptyAttempts}
            variant="error"
            open={emptyAttempts > 0 && staged.length === 0}
          >
            <SectionMessage.Title>Nothing staged yet</SectionMessage.Title>
            <SectionMessage.Content>
              Tick at least one venue to add it.
            </SectionMessage.Content>
          </SectionMessage>

          {/* Search and the type filter narrow the visible rows together;
              neither touches the staged selection tracked in `selected`. */}
          <Inline space={2} alignY="input">
            <SearchField
              aria-label="Search venues"
              placeholder="Search by name or city"
              value={search}
              onChange={setSearch}
              width={64}
            />
            <Select
              aria-label="Filter by type"
              value={type}
              onChange={setType}
              width={40}
            >
              <Select.Option id="all">All types</Select.Option>
              {types.map(t => (
                <Select.Option key={t} id={t}>
                  {t}
                </Select.Option>
              ))}
            </Select>
          </Inline>

          {/* The staged set stays on screen as removable tags no matter what
              the search and filter are doing, including when the list below is
              empty. The rail is always rendered, with a muted hint when empty,
              so staging the first venue never shifts the table. Removing a tag
              unstages that venue. */}
          <Tag.Group
            label={`Staged (${staged.length})`}
            selectionMode="none"
            onRemove={unstage}
            collapseAt={6}
            emptyState={() => (
              <Text variant="muted" fontSize="sm">
                No venues staged yet. Tick a row to add it.
              </Text>
            )}
          >
            {staged.map(venue => (
              <Tag key={venue.id} id={venue.id}>
                {venue.name}
              </Tag>
            ))}
          </Tag.Group>

          <Table
            aria-label="Venues"
            selectionMode="multiple"
            selectedKeys={selected}
            onSelectionChange={onSelectionChange}
          >
            <Table.Header>
              <Table.Column rowHeader>Venue</Table.Column>
              <Table.Column>City</Table.Column>
              <Table.Column>Type</Table.Column>
              <Table.Column>Capacity</Table.Column>
            </Table.Header>
            <Table.Body
              items={results}
              emptyState={() => (
                <EmptyState
                  title="No venues match"
                  description="Try a different search, or switch the type back to All types. Anything you already staged stays listed above."
                />
              )}
            >
              {venue => (
                <Table.Row id={venue.id}>
                  <Table.Cell>{venue.name}</Table.Cell>
                  <Table.Cell>{venue.city}</Table.Cell>
                  <Table.Cell>{venue.type}</Table.Cell>
                  <Table.Cell>{venue.capacity}</Table.Cell>
                </Table.Row>
              )}
            </Table.Body>
          </Table>
        </Stack>
      </Dialog.Content>
      <Dialog.Actions>
        <Button variant="secondary" slot="close">
          Cancel
        </Button>
        {/* Stays active. An empty press is refused with the message above
            rather than blocked by a disabled control. */}
        <Button
          variant="primary"
          onPress={() => {
            if (staged.length === 0) {
              setEmptyAttempts(n => n + 1);
              return;
            }
            onConfirm(selected);
          }}
        >
          {staged.length === 0
            ? 'Add venues'
            : `Add ${staged.length} ${staged.length === 1 ? 'venue' : 'venues'}`}
        </Button>
      </Dialog.Actions>
    </>
  );
};

export default () => {
  const [added, setAdded] = useState<Set<Key>>(() => new Set());
  const addedVenues = venues.filter(venue => added.has(venue.id));

  const removeVenue = (keys: Set<Key>) => {
    setAdded(prev => {
      const next = new Set<Key>(prev);
      keys.forEach(key => next.delete(key));
      return next;
    });
  };

