  TextValue,
} from '@marigold/components';

interface Person {
  id: string;
  name: string;
  email: string;
  team: string;
}

// A stand-in for the directory a real access picker searches through.
const people: Person[] = [
  {
    id: 'mara-lindqvist',
    name: 'Mara Lindqvist',
    email: 'mara.lindqvist@northwind.co',
    team: 'Engineering',
  },
  {
