  {
    id: 'sofia-rossi',
    name: 'Sofia Rossi',
    email: 'sofia.rossi@northwind.co',
    team: 'Marketing',
  },
  {
    id: 'ben-carter',
    name: 'Ben Carter',
    email: 'ben.carter@northwind.co',
    team: 'Marketing',
  },
  {
    id: 'noah-weiss',
    name: 'Noah Weiss',
    email: 'noah.weiss@northwind.co',
