              aria-label="Filter by team"
              value={team}
              onChange={setTeam}
              width={40}
            >
              <Select.Option id="all">All teams</Select.Option>
              {teams.map(t => (
                <Select.Option key={t} id={t}>
                  {t}
                </Select.Option>
              ))}
            </Select>
          </Inline>

          {/* The staged set stays on screen as removable tags no matter what
              the search and filter are doing, including when the list below is
              empty. The rail is always rendered, with a muted hint when empty,
              so staging the first person never shifts the list. Removing a tag
              unstages that person. */}
          <Tag.Group
            label={`Staged (${staged.length})`}
            selectionMode="none"
            onRemove={unstage}
            collapseAt={6}
            emptyState={() => (
              <Text variant="muted" fontSize="sm">
                No people staged yet. Tick a name to add them.
              </Text>
            )}
          >
            {staged.map(person => (
              <Tag key={person.id} id={person.id}>
                {person.name}
              </Tag>
            ))}
          </Tag.Group>

          {/* People are labels with a supporting email, not a grid of columns,
              so the results collection is a SelectList rather than a Table.
              Only the collection differs from the venue pick above. The list is
              its own boxed, scrolling surface, so it is not wrapped in a
              Scrollable (which would clip its rounded frame); the dialog scrolls
              instead. */}
          <SelectList
            aria-label="People"
            selectionMode="multiple"
            items={results}
            selectedKeys={selected}
            onChange={onChange}
            emptyState={
              <EmptyState
                title="No people match"
                description="Try a different search or team. Anyone you already staged stays listed above."
              />
            }
          >
            {(person: Person) => (
              <SelectList.Option id={person.id} textValue={person.name}>
                <TextValue>{person.name}</TextValue>
                <Description>{person.email}</Description>
              </SelectList.Option>
            )}
          </SelectList>
        </Stack>
      </Dialog.Content>
      <Dialog.Actions>
        <Button variant="secondary" slot="close">
          Cancel
        </Button>
        {/* Stays active. An empty press is refused with the message above
            rather than blocked by a disabled control. */}
        <Button
          variant="primary"
          onPress={() => {
            if (staged.length === 0) {
              setEmptyAttempts(n => n + 1);
              return;
            }
            onConfirm(selected);
          }}
        >
          {staged.length === 0
            ? 'Add people'
            : `Add ${staged.length} ${staged.length === 1 ? 'person' : 'people'}`}
        </Button>
      </Dialog.Actions>
    </>
  );
};

export default () => {
  const [added, setAdded] = useState<Set<Key>>(() => new Set());
  const addedNames = people
    .filter(person => added.has(person.id))
    .map(person => person.name);

